1	import type { ICtx, ScheduleHandle } from "@threenative/core";
2	import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
3	import { type Group, Vector3 } from "three";
4	import { directSpaceState } from "../physics.js";
5	import { createEnemyVisual } from "../render/shapes.js";
6	import type { GameState } from "../state.js";
7	import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";
8	
9	type GameCtx = ICtx<GameState, IPhysicsContext>;
10	
11	const PATROL_SPEED = 2.5;
12	const CHASE_SPEED = 3.8;
13	const VISION_RANGE = 8;
14	const FIRE_COOLDOWN = 1.2;
15	const FIRE_RANGE = 12;
16	
17	export class Enemy {
18	  readonly mesh: Group;
19	  readonly body: CharacterBody3D;
20	  readonly tags = ["hostile", "enemy"];
21	  health: number;
22	  alive = true;
23	  #onFire: (origin: Vector3) => void;
24	  #patrolPoints: Vector3[];
25	  #currentPatrolIndex = 0;
26	  #chasing = false;
27	  #playerLastSeenPos: Vector3 | undefined;
28	  #visionShape = CollisionShape3D.sphere(VISION_RANGE);
29	  #fireTimer = 0;
30	  #scanHandle: ScheduleHandle | undefined;
31	
32	  constructor(
33	    ctx: GameCtx,
34	    materials: Parameters<typeof createEnemyVisual>[0],
35	    position: Vector3,
36	    patrolPoints: Vector3[],
37	    onFire: (origin: Vector3) => void = () => undefined,
38	  ) {
39	    this.#onFire = onFire;
40	    this.#patrolPoints = patrolPoints.length > 0 ? patrolPoints : [position];
41	    this.health = 60;
42	    this.mesh = createEnemyVisual(materials);
43	    this.mesh.position.copy(position);
44	    ctx.add(this.mesh);
45	    this.body = new CharacterBody3D({
46	      autostep: { maxHeight: 0.25, minWidth: 0.18 },
47	      collisionLayer: HOSTILE_LAYER,
48	      collisionMask: WORLD_LAYER | PLAYER_LAYER,
49	      object: this.mesh,
50	      physics: ctx.physics,
51	      shape: CollisionShape3D.capsule(0.35, 0.7),
52	    });
53	  }
54	
55	  startVisionScanning(ctx: GameCtx, playerBodyId: number): void {
56	    const scan = (): void => {
57	      if (!this.alive) return;
58	      const hits = directSpaceState(ctx.physics).intersectShape({
59	        collisionMask: PLAYER_LAYER,
60	        maxResults: 4,
61	        position: this.mesh.position,
62	        shape: this.#visionShape,
63	      });
64	      const playerSeen = hits.some((hit) => hit.body.id === playerBodyId);
65	      if (playerSeen) {
66	        this.#chasing = true;
67	        this.#playerLastSeenPos = undefined;
68	      } else {
69	        this.#chasing = false;
70	      }
71	      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
72	    };
73	    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
74	  }
75	
76	  update(ctx: GameCtx, playerPos: Vector3, dt: number): void {
77	    if (!this.alive) return;
78	
79	    this.#fireTimer -= dt;
80	
81	    if (this.#chasing) {
82	      this.#playerLastSeenPos = playerPos.clone();
83	      const direction = playerPos
84	        .clone()
85	        .sub(this.mesh.position)
86	        .normalize();
87	      this.body.velocity.x = direction.x * CHASE_SPEED;
88	      this.body.velocity.z = direction.z * CHASE_SPEED;
89	
90	      const distToPlayer = this.mesh.position.distanceTo(playerPos);
91	      if (distToPlayer < FIRE_RANGE && this.#fireTimer <= 0) {
92	        this.#fireTimer = FIRE_COOLDOWN;
93	        this.#onFire(this.rifleOrigin());
94	      }
95	    } else {
96	      this.patrol();
97	    }
98	
99	    this.body.moveAndSlide(dt);
100	  }
101	
