import type { ICtx, ScheduleHandle } from "@threenative/core";
import {
  CharacterBody3D,
  CollisionShape3D,
  type IPhysicsContext,
  NavigationAgent3D,
} from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { createEnemyVisual, createRifleVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { directSpaceState } from "../physics.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_RADIUS = 6;
const VISION_RANGE = 8;
const PATROL_SPEED = 1.5;
const CHASE_SPEED = 3;
const FIRE_COOLDOWN = 1.2;
const SCAN_INTERVAL = 0.2;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly navAgent: NavigationAgent3D;
  readonly tags = ["hostile", "enemy"];
  health: number;
  alive = true;
  acquired = false;
  #onFire: (origin: Vector3, direction: Vector3) => void;
  #scanHandle: ScheduleHandle | undefined;
  #fireTimer = 0;
  #patrolTarget = new Vector3();
  #visionShape = CollisionShape3D.sphere(VISION_RANGE);
  #rifle: Group;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3, direction: Vector3) => void;
    } = {},
  ) {
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.45, 0.38),
    });

    this.navAgent = new NavigationAgent3D({
      object: this.mesh,
      physics: ctx.physics,
      radius: 0.5,
    });

    this.#rifle = createRifleVisual(materials);
    this.mesh.add(this.#rifle);
    this.#rifle.position.set(0.45, 0.5, -0.3);
    this.#rifle.rotation.z = Math.PI / 6;

    this.#patrolTarget.copy(position);
  }

  startScanning(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 4,
        position: this.mesh.position,
        shape: this.#visionShape,
      });
      this.acquired = hits.some((hit) => hit.body.id === playerBodyId);
      this.#scanHandle = ctx.after(SCAN_INTERVAL, scan);
    };
    this.#scanHandle = ctx.after(SCAN_INTERVAL, scan);
  }

  update(ctx: GameCtx, playerPos: Vector3, dt: number): void {
    if (!this.alive) return;

    const moveSpeed = this.acquired ? CHASE_SPEED : PATROL_SPEED;

    if (!this.acquired) {
      const distToPatrol = this.mesh.position.distanceTo(this.#patrolTarget);
      if (distToPatrol < 1) {
        this.#patrolTarget.set(
          this.mesh.position.x + (ctx.random.range(-1, 1) * PATROL_RADIUS),
          this.mesh.position.y,
          this.mesh.position.z + (ctx.random.range(-1, 1) * PATROL_RADIUS),
        );
      }
    }

    const targetPos = this.acquired ? playerPos : this.#patrolTarget;
    const direction = targetPos.clone().sub(this.mesh.position).normalize();

    this.body.velocity.x = direction.x * moveSpeed;
    this.body.velocity.z = direction.z * moveSpeed;
    this.body.moveAndSlide(dt);

    if (this.acquired) {
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0) {
        const fireOrigin = this.mesh.position.clone().add(new Vector3(0.5, 0.5, -0.3));
        const aimDir = playerPos.clone().sub(fireOrigin).normalize();
        this.#onFire(fireOrigin, aimDir);
        this.#fireTimer = FIRE_COOLDOWN;
      }
    }
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      acquired: this.acquired,
      alive: this.alive,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.navAgent.dispose();
    this.mesh.removeFromParent();
  }
}

