const registerEnemy = (
  id: string,
  position: Vector3,
  patrolPoints: Vector3[],
): Enemy => {
  const enemy = new Enemy(ctx, materials, position, patrolPoints, createEnemyProjectile);
  enemies.set(enemy.body.body.id, enemy);
  ctx.entities.add(id, enemy);
  enemy.startVisionScanning(ctx, getPlayer().body.body.id);
  return enemy;
};

